// TestReadSessionFile_ReadsThroughTheStore is the read half's happy path: with a
// RepoPath, the ref resolves to a name inside the agent's session directory and
// is read through that root.
func TestReadSessionFile_ReadsThroughTheStore(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	ag := &storeStubAgent{dir: dir, resolve: joinResolve}
	require.NoError(t, os.WriteFile(filepath.Join(dir, "abc123.jsonl"), []byte("line\n"), 0o600))

	got, err := agent.ReadSessionFile(ag, filepath.Join(dir, "abc123.jsonl"), t.TempDir())
	require.NoError(t, err)
	assert.Equal(t, "line\n", string(got))
}

// TestReadSessionFile_RejectsRefOutsideTheStore is the property the whole change
// exists for. The WRITE half already refuses a SessionRef outside the agent's
// session directory (sessionStoreForWrite); the read half took the path on trust,
// and reads are what pull transcript content into checkpoints.
func TestReadSessionFile_RejectsRefOutsideTheStore(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	outside := t.TempDir()
	secret := filepath.Join(outside, "secret.jsonl")
	require.NoError(t, os.WriteFile(secret, []byte("SECRET\n"), 0o600))
	ag := &storeStubAgent{dir: dir, resolve: joinResolve}

	got, err := agent.ReadSessionFile(ag, secret, t.TempDir())
	require.ErrorIs(t, err, agent.ErrOutsideSessionStore)
	assert.Empty(t, got, "a ref outside the session directory must not be read")
}

// TestReadSessionFile_RefusesSymlinkedSessionFile covers the planted-link case:
// a name inside the store that redirects out of it. os.ReadFile followed it.
func TestReadSessionFile_RefusesSymlinkedSessionFile(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	outside := t.TempDir()
	secret := filepath.Join(outside, "secret.jsonl")
	require.NoError(t, os.WriteFile(secret, []byte("SECRET\n"), 0o600))
	if err := os.Symlink(secret, filepath.Join(dir, "abc123.jsonl")); err != nil {
		t.Skipf("symlink not supported: %v", err)
	}
	ag := &storeStubAgent{dir: dir, resolve: joinResolve}

	got, err := agent.ReadSessionFile(ag, filepath.Join(dir, "abc123.jsonl"), t.TempDir())
	require.Error(t, err)
	assert.NotContains(t, string(got), "SECRET", "a symlinked session file must not be followed")
}

// TestReadSessionFile_WithoutRepoPathAnchorsOnTheRefsOwnDirectory mirrors
// sessionStoreForWrite's documented fallback: with no RepoPath there is no other
// candidate, and the ref came from Entire's own resolution rather than an agent
// payload. Pinned so the fallback is a decision rather than an accident.
func TestReadSessionFile_WithoutRepoPathAnchorsOnTheRefsOwnDirectory(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	ag := &storeStubAgent{dir: t.TempDir(), resolve: joinResolve}
	require.NoError(t, os.WriteFile(filepath.Join(dir, "abc123.jsonl"), []byte("line\n"), 0o600))

	got, err := agent.ReadSessionFile(ag, filepath.Join(dir, "abc123.jsonl"), "")
	require.NoError(t, err)
	assert.Equal(t, "line\n", string(got))
}

// TestReadSessionFile_RequiresASessionRef mirrors WriteSessionFile's guard.
func TestReadSessionFile_RequiresASessionRef(t *testing.T) {
	t.Parallel()

	ag := &storeStubAgent{dir: t.TempDir(), resolve: joinResolve}
	_, err := agent.ReadSessionFile(ag, "", t.TempDir())
	require.Error(t, err)
}

